UPDATE board_todos SET title = #{row.title}, content = #{row.content}, completed = #{row.completed},
    version_number = version_number + 1, updated_at = CURRENT_TIMESTAMP(6)
WHERE todo_id = #{row.todoId} AND  AND version_number = #{row.versionNumber}

UPDATE board_todos SET author_id = #{memberId}, guest_id = NULL,
    version_number = version_number + 1, updated_at = CURRENT_TIMESTAMP(6)
WHERE author_id IS NULL AND guest_id = #{guestId} AND todo_id <= #{throughTodoId}
